import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track recent and overall behavior cheaply in one pass over a suffix.
    opp_c = 0
    opp_d = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1

    my_last, opp_last = history[-1]

    # Immediate obvious cases.
    if opp_d == 0:
        # Opponent has never defected. Mostly cooperate, but take a few
        # well-spaced exploitation shots once trust is established.
        if n >= 97:
            return 'D'
        if n > 25 and n % 11 == 0 and rng.random() < 0.55:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'

    # Look at the recent window for repair/punishment decisions.
    k = 8 if n >= 8 else n
    rec_opp_c = 0
    rec_opp_d = 0
    rec_my_c = 0
    start = n - k
    for i in range(start, n):
        a, b = history[i]
        if b == 'C':
            rec_opp_c += 1
        else:
            rec_opp_d += 1
        if a == 'C':
            rec_my_c += 1

    # Endgame: exploit cooperative opponents, defend against defectors.
    if n >= 94:
        if opp_c * 100 >= n * 60:
            return 'D'
        if opp_d * 100 >= n * 70:
            return 'D'
        return 'D' if opp_last == 'C' else 'C'

    # Opponent just defected.
    if opp_last == 'D':
        # Long consistent defector: don't keep feeding them.
        if opp_d >= 4 and opp_d * 3 >= n:
            return 'D'
        # If the recent streak is just one defection after cooperation,
        # retaliate once but be ready to forgive.
        if rec_opp_d <= 1 and rec_opp_c >= 5:
            return 'D'
        # If opponent has been mostly cooperative, retaliate then resume.
        if opp_c * 100 >= n * 70:
            return 'D'
        # Forgiveness to break alternating retaliation loops.
        if n >= 2 and history[-2][1] == 'C' and rng.random() < 0.35:
            return 'C'
        if rec_opp_d >= 4:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we just punished and they returned to cooperation, resume cooperation.
    if my_last == 'D' and opp_last == 'C':
        return 'C'

    # Heavily cooperative opponent: mostly cooperate with occasional probes.
    if opp_c * 100 >= n * 88 and n > 20:
        if n % 9 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Recent defection streak from opponent should be answered firmly.
    if rec_opp_d >= 3 and rec_opp_c <= 2:
        return 'D'

    # If our cooperation has been taken advantage of a lot, tighten up.
    if my_c * 100 >= n * 80 and opp_d * 100 >= n * 30:
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Default: cooperate to maintain mutual cooperation value.
    return 'C'
